SELECT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='bk_agent' AND table_name='agent_event_audit' AND column_name='event_id' AND data_type='varchar' AND character_maximum_length=64) AND (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='bk_agent' AND table_name='agent_event_audit' AND ((index_name='uk_agent_event_audit_event_id' AND non_unique=0 AND seq_in_index=1 AND column_name='event_id') OR (index_name='idx_agent_event_audit_session_sequence' AND ((seq_in_index=1 AND column_name='session_id') OR (seq_in_index=2 AND column_name='id'))) OR (index_name='idx_agent_event_audit_session_task_sequence' AND ((seq_in_index=1 AND column_name='session_id') OR (seq_in_index=2 AND column_name='task_id') OR (seq_in_index=3 AND column_name='id')))))=6;
